using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut = new();

        public void Dispose() => _sut.Dispose();

        private void DrainQueue()
        {
            while (_sut.ReceiveNotification() != null) { }
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            DrainQueue();

            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            DrainQueue();

            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_ContainsDeletedInMessage()
        {
            DrainQueue();

            _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "user1");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Engineering", notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultUserName_SetsSystem()
        {
            DrainQueue();

            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            DrainQueue();

            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_DequeuedInFifoOrder()
        {
            DrainQueue();

            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            Assert.Equal("A", _sut.ReceiveNotification()!.EntityType);
            Assert.Equal("B", _sut.ReceiveNotification()!.EntityType);
            Assert.Equal("C", _sut.ReceiveNotification()!.EntityType);
            Assert.Null(_sut.ReceiveNotification());
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNow()
        {
            DrainQueue();
            var before = DateTime.Now;

            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op in the in-memory implementation
            var exception = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_NullDisplayName_FallsBackToId()
        {
            DrainQueue();

            _sut.SendNotification("Instructor", "7", null, EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 7", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_FallsBackToId()
        {
            DrainQueue();

            _sut.SendNotification("Instructor", "7", "  ", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 7", notification.Message);
        }
    }
}

