using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.HttpContext, Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student SeedStudent(string first = "John", string last = "Doe", DateTime? enrollmentDate = null)
        {
            var student = new Student
            {
                FirstMidName = first,
                LastName = last,
                EnrollmentDate = enrollmentDate ?? new DateTime(2020, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        // --- Index ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            SeedStudent("Zara", "Adams");
            SeedStudent("Alice", "Brown");

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Brown", model[1].LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsDescendingOrder()
        {
            SeedStudent("Zara", "Adams");
            SeedStudent("Alice", "Zephyr");

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Equal("Zephyr", model[0].LastName);
            Assert.Equal("Adams", model[1].LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsOrderedByEnrollmentDate()
        {
            SeedStudent("Late", "Student", new DateTime(2022, 1, 1));
            SeedStudent("Early", "Student", new DateTime(2018, 1, 1));

            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Equal("Early", model[0].FirstMidName);
            Assert.Equal("Late", model[1].FirstMidName);
        }

        [Fact]
        public void Index_DateDescSort_ReturnsReverseChronological()
        {
            SeedStudent("Late", "Student", new DateTime(2022, 1, 1));
            SeedStudent("Early", "Student", new DateTime(2018, 1, 1));

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Equal("Late", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedStudent("Alice", "Johnson");
            SeedStudent("Bob", "Smith");

            var result = _controller.Index(null, null, "John", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Single(model);
            Assert.Equal("Johnson", model[0].LastName);
        }

        [Fact]
        public void Index_SearchStringNull_UsesCurrentFilter()
        {
            SeedStudent("Alice", "Johnson");
            SeedStudent("Bob", "Smith");

            var result = _controller.Index(null, "Smith", null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
        }

        [Fact]
        public void Index_SearchStringProvided_ResetsPageToOne()
        {
            SeedStudent("Alice", "Test");

            _controller.Index(null, null, "Test", 5);

            // When searchString is provided, page resets to 1
            Assert.Equal("Test", _controller.ViewBag.CurrentFilter);
        }

        [Fact]
        public void Index_SetsViewBagSortParms()
        {
            _controller.Index(null, null, null, null);

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_SortOrderDate_DateSortParmIsDateDesc()
        {
            _controller.Index("Date", null, null, null);

            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsStudentWithEnrollments()
        {
            var student = SeedStudent();
            var course = new Course { CourseID = 100, Title = "Math", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 100, Grade = Grade.A });
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
            Assert.Single(model.Enrollments);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultStudent()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_MinValueDate_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_DateBeforeSqlRange_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(student, result.Model);
            Assert.Empty(_context.Students);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsStudentView()
        {
            var student = SeedStudent();

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(student.ID, ((Student)result.Model).ID);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = SeedStudent();
            student.FirstMidName = "Updated";

            var result = _controller.Edit(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_MinValueDate_AddsModelError()
        {
            var student = SeedStudent();
            student.EnrollmentDate = DateTime.MinValue;

            var result = _controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            var student = SeedStudent();
            _controller.ModelState.AddModelError("LastName", "Required");

            var result = _controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            var student = SeedStudent();

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(student.ID, ((Student)result.Model).ID);
        }

        // --- Delete POST ---

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            var student = SeedStudent();

            var result = _controller.DeleteConfirmed(student.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Students);
        }
    }
}

