using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _envMock = new Mock<IWebHostEnvironment>();
            _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
            _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            _loggerMock = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.HttpContext, Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department SeedDepartment(string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(int courseId = 1001, string title = "Physics", int credits = 3, Department dept = null)
        {
            dept ??= SeedDepartment();
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = credits,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithCourseList()
        {
            var dept = SeedDepartment();
            SeedCourse(1001, "Physics", 3, dept);
            SeedCourse(1002, "Chemistry", 4, dept);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourseWithDepartment()
        {
            var course = SeedCourse();

            var result = _controller.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
            Assert.NotNull(model.Department);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithDepartmentSelectList()
        {
            SeedDepartment("Math");

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidCourseNoImage_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_Post_InvalidExtension_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Art", Credits = 3, DepartmentID = dept.DepartmentID };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.exe");
            fileMock.Setup(f => f.Length).Returns(100);

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 2000, Title = "Art", Credits = 3, DepartmentID = dept.DepartmentID };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.jpg");
            fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024);

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains(
                _controller.ModelState["teachingMaterialImage"]!.Errors,
                e => e.ErrorMessage.Contains("5MB"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 2000, Credits = 3 };

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Courses);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);
            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsCourseView()
        {
            var course = SeedCourse();
            var result = _controller.Edit(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(course.CourseID, ((Course)result.Model).CourseID);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidCourseNoImage_RedirectsToIndex()
        {
            var course = SeedCourse();
            course.Title = "Updated Title";

            var result = _controller.Edit(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidExtension_ReturnsViewWithError()
        {
            var course = SeedCourse();
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.txt");
            fileMock.Setup(f => f.Length).Returns(100);

            var result = _controller.Edit(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_ReturnsViewWithError()
        {
            var course = SeedCourse();
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("pic.png");
            fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024);

            var result = _controller.Edit(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            var course = SeedCourse();
            _controller.ModelState.AddModelError("Title", "Required");

            var result = _controller.Edit(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);
            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsCourseView()
        {
            var course = SeedCourse();
            var result = _controller.Delete(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
        }

        // --- Delete POST ---

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var course = SeedCourse();

            var result = _controller.DeleteConfirmed(course.CourseID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImagePath_StillRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3000,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/nonexistent.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(course.CourseID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }
    }
}

