using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.HttpContext, Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor SeedInstructor(string first = "Kim", string last = "Abercrombie",
            DateTime? hireDate = null, List<CourseAssignment> assignments = null)
        {
            var instructor = new Instructor
            {
                FirstMidName = first,
                LastName = last,
                HireDate = hireDate ?? new DateTime(2000, 1, 1),
                CourseAssignments = assignments ?? new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        private Course SeedCourse(int id = 1050, string title = "Chemistry")
        {
            var dept = new Department { Name = "Eng", Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            var course = new Course { CourseID = id, Title = title, Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // --- Index ---

        [Fact]
        public void Index_NoParams_ReturnsInstructorIndexData()
        {
            SeedInstructor("Kim", "Abercrombie");
            SeedInstructor("Roger", "Zheng");

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            var course = SeedCourse();
            var instructor = SeedInstructor();
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });
            _context.SaveChanges();
            // Reload to get navigation properties
            _context.Entry(instructor).Collection(i => i.CourseAssignments).Load();

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructorView()
        {
            var instructor = SeedInstructor();

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
            Assert.Equal("Abercrombie", model.LastName);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithCourseData()
        {
            SeedCourse();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            var course = SeedCourse(5001, "Biology");
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Prof",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Instructors.Include(Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions
                .Include(_context.Instructors, i => i.CourseAssignments).Expression)
                .First();
            // Verify course assignment was persisted
            Assert.NotEmpty(_context.CourseAssignments);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            SeedCourse(); // Needed for PopulateAssignedCourseData

            var result = _controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Instructors);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);
            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsInstructorView()
        {
            var instructor = SeedInstructor();

            var result = _controller.Edit(instructor.ID) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);
            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsInstructorView()
        {
            var instructor = SeedInstructor();

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(instructor.ID, ((Instructor)result.Model).ID);
        }

        // --- Delete POST ---

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            var instructor = SeedInstructor();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_InstructorAdministersDepartment_NullsOutAdministrator()
        {
            var instructor = SeedInstructor();
            var dept = new Department
            {
                Name = "Math",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept!.InstructorID);
        }
    }
}

