using System;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class ModelTests
    {
        // --- Person / Student / Instructor ---

        [Fact]
        public void Person_FullName_ReturnsLastNameCommaFirst()
        {
            var student = new Student { LastName = "Doe", FirstMidName = "John" };
            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void Student_Enrollments_CanBeInitialized()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Today,
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };
            Assert.NotNull(student.Enrollments);
            Assert.Empty(student.Enrollments);
        }

        [Fact]
        public void Instructor_FullName_ReturnsCorrectFormat()
        {
            var instructor = new Instructor { LastName = "Smith", FirstMidName = "Jane" };
            Assert.Equal("Smith, Jane", instructor.FullName);
        }

        [Fact]
        public void Instructor_CourseAssignments_CanBeSet()
        {
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Prof",
                HireDate = DateTime.Today,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            Assert.Empty(instructor.CourseAssignments);
        }

        [Fact]
        public void Instructor_OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Prof",
                HireDate = DateTime.Today
            };
            var office = new OfficeAssignment { Location = "Room 101", Instructor = instructor };
            instructor.OfficeAssignment = office;

            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
            Assert.Same(instructor, office.Instructor);
        }

        // --- Course ---

        [Fact]
        public void Course_Properties_RoundTrip()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/images/chem.jpg"
            };
            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/images/chem.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_NavigationProperties_CanBeSet()
        {
            var dept = new Department { Name = "Eng" };
            var course = new Course
            {
                CourseID = 100,
                Title = "Test",
                Credits = 3,
                Department = dept,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            Assert.Same(dept, course.Department);
            Assert.Empty(course.Enrollments);
            Assert.Empty(course.CourseAssignments);
        }

        // --- Department ---

        [Fact]
        public void Department_Properties_RoundTrip()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Math",
                Budget = 250000m,
                StartDate = new DateTime(2020, 9, 1),
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3 }
            };
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Math", dept.Name);
            Assert.Equal(250000m, dept.Budget);
            Assert.Equal(new DateTime(2020, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
            Assert.Equal(new byte[] { 1, 2, 3 }, dept.RowVersion);
        }

        [Fact]
        public void Department_InstructorID_Nullable()
        {
            var dept = new Department { Name = "Test", InstructorID = null };
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Department_Courses_CanBeSet()
        {
            var dept = new Department
            {
                Name = "Test",
                Courses = new System.Collections.Generic.List<Course>()
            };
            Assert.Empty(dept.Courses);
        }

        // --- Enrollment ---

        [Fact]
