using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(7, context.Courses.Count());
        }

        [Fact]
        public void Initialize_VerifiesSpecificStudentData()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var carson = context.Students.Single(s => s.LastName == "Alexander");
            Assert.Equal("Carson", carson.FirstMidName);
            Assert.Equal(new DateTime(2010, 9, 1), carson.EnrollmentDate);
        }

        [Fact]
        public void Initialize_VerifiesDepartmentAdministratorLinks()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var english = context.Departments.Single(d => d.Name == "English");
            var admin = context.Instructors.Find(english.InstructorID);
            Assert.Equal("Abercrombie", admin!.LastName);
        }

        [Fact]
        public void Initialize_VerifiesEnrollmentGrades()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var enrollment = context.Enrollments
                .Where(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry")
                .Single();
            Assert.Equal(Grade.A, enrollment.Grade);
        }

        [Fact]
        public void Initialize_SomeEnrollmentsHaveNoGrade()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var noGrade = context.Enrollments
                .Where(e => e.Student.LastName == "Anand" && e.Course.Title == "Chemistry")
                .Single();
            Assert.Null(noGrade.Grade);
        }
    }
}

