using System;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateWithInMemoryProvider()
        {
            using var context = TestDbContextFactory.Create();
            Assert.NotNull(context);
        }

        [Fact]
        public void SchoolContext_DbSets_AreAccessible()
        {
            using var context = TestDbContextFactory.Create();

            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.People);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            var dbName = Guid.NewGuid().ToString();
            using (var context = TestDbContextFactory.Create(dbName))
            {
                context.Students.Add(new Student
                {
                    FirstMidName = "Test",
                    LastName = "Student",
                    EnrollmentDate = new DateTime(2020, 1, 1)
                });
                context.SaveChanges();
            }

            using (var context = TestDbContextFactory.Create(dbName))
            {
                var student = context.Students.Find(1);
                Assert.NotNull(student);
                Assert.Equal("Test", student.FirstMidName);
                Assert.Equal("Student", student.LastName);
            }
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContextFactory.Create();

            var instructor = new Instructor
            {
                FirstMidName = "A",
                LastName = "B",
                HireDate = DateTime.Today
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Today };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 1, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
            context.CourseAssignments.Add(ca);
            context.SaveChanges();

            var found = context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(found);
        }
    }
}

