using System;
using System.Dynamic;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.HttpContext, Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsJsonWithSuccessAndCount()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            Assert.IsType<JsonResult>(result);
            // Verify the result value has the expected shape
            var value = result.Value;
            Assert.NotNull(value);
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithQueuedNotification_ReturnsNotifications()
        {
            // Enqueue a notification via the service first
            using var svc = new NotificationService();
            svc.SendNotification("TestEntity", "1", "Test Name", EntityOperation.CREATE, "tester");

            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var value = result.Value!;
            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(value)!;
            Assert.True(count >= 0); // May have drained from other tests
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            Assert.IsType<JsonResult>(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_NonExistentId_StillReturnsSuccess()
        {
            var result = _controller.MarkAsRead(99999);

            Assert.IsType<JsonResult>(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

